package org.apache.commons.codec.language;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.codec.EncoderException;
import org.apache.commons.codec.StringEncoder;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Caverphone_caverphone_TriageGen2Test {

    private Caverphone caverphone;

    @Before
    public void setUp() {
        caverphone = new Caverphone();
    }





    @Test
    public void testCaverphone_StandardWord() {
        // "apple" -> "appl" (e removed) -> "ap-pl" -> "A-p-l" -> "A-P-L" -> "APL1111111" -> "APL1111111"
        // Let's trace "apple" carefully:
        // 1. apple
        // 2. apple
        // 2.5. appl (remove e)
        // 4. a->A, p->P, l->L
        // 5. remove 2,3
        // Result: APL1111111 (substring 0,10)
        String result = caverphone.caverphone("apple");
        assertNotNull(result);
        assertTrue(result.length() == 10);
    }














}

package org.apache.commons.codec.language;

import java.io.*;
