import org.junit.Test;
import static org.junit.Assert.*;

public class Caverphone_caverphone_TriageGen2Test {

    private Caverphone caverphone;

    @Before
    public void setUp() {
        caverphone = new Caverphone();
    }









    @Test
    public void testCaverphone_Replacements() {
        // cq -> 2q -> q -> k
        // ci -> si
        // ce -> se
        // cy -> sy
        // tch -> 2ch -> ch -> kh
        // c -> k
        // q -> k
        // x -> k
        // v -> f
        // dg -> 2g -> g -> k
        // tio -> sio
        // tia -> sia
        // d -> t
        // ph -> fh
        // b -> p
        // sh -> s2 -> s
        // z -> s

        // Test ci
        assertTrue(caverphone.caverphone("city").startsWith(caverphone.caverphone("sity").substring(0, 4)));
        // Test ph
        assertTrue(caverphone.caverphone("phone").startsWith(caverphone.caverphone("fone").substring(0, 4)));
    }










}

package org.apache.commons.codec.language;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.codec.EncoderException;
import org.apache.commons.codec.StringEncoder;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Caverphone_caverphone_TriageGen2Test {

    private Caverphone caverphone;

    @Before
    public void setUp() {
        caverphone = new Caverphone();
    }











    @Test
    public void testCaverphone_VowelsAndConsonants() {
        // Test [aeiou] -> A or 3
        // Test s+, t+, p+, k+, f+, m+, n+
        // Test w3, wh3, w$, w, h, r3, r$, r, l3, l$, l

        String res1 = caverphone.caverphone("mass");
        String res2 = caverphone.caverphone("mas");
        // Both should result in similar phonetic codes due to s+ replacement
        assertEquals(res1.substring(0, 5), res2.substring(0, 5));
    }








}

